// Upstream CSS, line for line, with component-prefixed parts (data-slot),
// keyframes (pop-out-*) and colors (--pop-out-*). Mirrored as a whole in a
// right-to-left context. The base block grows by animating `height`, as
// upstream does. React 19 hoists this <style> into <head> once, however many
// instances render.
const css = `
[data-slot="pop-out-stack"] {
  position: absolute;
  bottom: 35%;
  width: 100%;
  display: grid;
  row-gap: 3px;
  justify-items: center;
  align-content: end;
}
[data-slot="pop-out-stack"]:dir(rtl) {
  scale: -1 1;
}
[data-slot="pop-out-block"] {
  position: relative;
  width: 120px;
  height: 40px;
  border-radius: 8px;
  transform-origin: bottom center;
}
[data-slot="pop-out-block"]:nth-child(1) {
  background-color: var(--pop-out-top, #aaa);
  animation: pop-out-jump 0.7s ease-in-out 0.3s both;
}
[data-slot="pop-out-block"]:nth-child(2) {
  background-color: var(--pop-out-base, #888);
  animation: pop-out-push 0.5s ease-in-out 0.2s both;
}
@keyframes pop-out-jump {
  from {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-40%) rotate(6deg);
  }
  60% {
    transform: translateY(0%);
  }
  80% {
    transform: translateY(-20%) rotate(-3deg);
  }
  to {
    transform: translateY(0);
  }
}
@keyframes pop-out-push {
  from {
    height: 0;
  }
  60% {
    height: 48px;
  }
  to {
    height: 40px;
  }
}

/* Reduced motion: no motion; both blocks show their resting state. */
@media (prefers-reduced-motion: reduce) {
  [data-slot="pop-out-block"]:nth-child(n) {
    animation: none;
  }
}
`;

/**
 * A block pushes up from below and pops the block on top of it into a small
 * hop, once on mount. Remount it (change its `key`) to play it again.
 */
function PopOut({ className, ...props }: React.ComponentProps<"div">) {
  const labelled =
    props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
  return (
    <div
      data-slot="pop-out"
      role={labelled ? "img" : undefined}
      aria-hidden={labelled ? undefined : true}
      className={cn(
        "relative aspect-square w-full max-w-80 overflow-hidden bg-[var(--pop-out-surface,#fff)]",
        className,
      )}
      {...props}
    >
      <style href="designfrom-pop-out" precedence="default">
        {css}
      </style>
      <div data-slot="pop-out-stack">
        <div data-slot="pop-out-block" />
        <div data-slot="pop-out-block" />
      </div>
    </div>
  );
}

export { PopOut };
